.sl-hero-wrapper {
    --sl-bg: var(--smartlearn-bg, #050508);
    --sl-surface: var(--smartlearn-card-bg, rgba(20, 20, 30, 0.65));
    --sl-surface-hover: var(--smartlearn-card-bg, rgba(30, 30, 45, 0.85));
    --sl-border: var(--smartlearn-card-border, rgba(255, 255, 255, 0.08));
    --sl-border-active: var(--smartlearn-primary, rgba(99, 102, 241, 0.4));
    --sl-text-main: var(--smartlearn-text, #F8FAFC);
    --sl-text-muted: var(--smartlearn-text-muted, #94A3B8);
    --sl-primary: var(--smartlearn-primary, #6366F1);
    --sl-primary-hover: var(--smartlearn-primary-hover, #4F46E5);
    --sl-cyan: #06B6D4;
    --sl-success: #10B981;
    --sl-radius: 16px;
    --sl-font: var(--smartlearn-body-font, 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif);
}

.sl-hero-wrapper {
    position: relative;
    width: 100%;
    min-height: 85vh;
    background-color: var(--sl-bg);
    color: var(--sl-text-main);
    font-family: var(--sl-font);
    overflow: hidden;
    padding: 5rem 2rem;
    display: flex;
    align-items: center;
    box-sizing: border-box;
}

.sl-hero-wrapper *,
.sl-hero-wrapper *::before,
.sl-hero-wrapper *::after {
    box-sizing: inherit;
}

/* Ambient Backdrops */
.sl-ambient-light {
    position: absolute;
    width: 500px;
    height: 500px;
    border-radius: 50%;
    filter: blur(140px);
    opacity: 0.18;
    pointer-events: none;
    z-index: 0;
}

.sl-ambient-indigo {
    top: -10%;
    left: -5%;
    background: radial-gradient(circle, #6366F1, transparent 70%);
}

.sl-ambient-cyan {
    bottom: -15%;
    right: 5%;
    background: radial-gradient(circle, #06B6D4, transparent 70%);
}

.sl-hero-container {
    position: relative;
    z-index: 1;
    max-width: 1280px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1.15fr 0.85fr;
    gap: 4rem;
    align-items: center;
}

/* Badge */
.sl-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 14px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--sl-border);
    border-radius: 100px;
    font-size: 0.825rem;
    font-weight: 500;
    color: #E2E8F0;
    margin-bottom: 1.5rem;
    backdrop-filter: blur(8px);
}

.sl-badge-indicator {
    width: 8px;
    height: 8px;
    background: var(--sl-success);
    border-radius: 50%;
    box-shadow: 0 0 10px var(--sl-success);
}

/* Typography */
.sl-hero-title {
    font-size: clamp(2.5rem, 4.5vw, 4rem);
    font-weight: 800;
    line-height: 1.12;
    letter-spacing: -0.03em;
    margin: 0 0 1.25rem 0;
    color: #FFFFFF;
}

.sl-title-gradient {
    background: linear-gradient(135deg, #818CF8 0%, #C084FC 50%, #38BDF8 100%);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

.sl-hero-subtitle {
    font-size: 1.125rem;
    line-height: 1.65;
    color: var(--sl-text-muted);
    margin: 0 0 2.25rem 0;
    max-width: 90%;
}

/* Feature Pills */
.sl-feature-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 2.5rem;
}

.sl-pill {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 0.65rem 1.15rem;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid var(--sl-border);
    border-radius: 100px;
    color: var(--sl-text-muted);
    font-family: inherit;
    font-size: 0.875rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.25s ease;
}

.sl-pill:hover {
    background: rgba(255, 255, 255, 0.07);
    color: #FFFFFF;
}

.sl-pill.active {
    background: rgba(99, 102, 241, 0.15);
    border-color: var(--sl-primary);
    color: #FFFFFF;
    box-shadow: 0 0 15px rgba(99, 102, 241, 0.25);
}

.sl-svg-icon {
    width: 18px;
    height: 18px;
    flex-shrink: 0;
}

/* CTA Buttons */
.sl-cta-group {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 3.5rem;
}

.sl-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 0.9rem 1.8rem;
    border-radius: 12px;
    font-size: 0.95rem;
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
    transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
    border: 1px solid transparent;
}

.sl-btn-primary {
    background: var(--sl-primary);
    color: #FFFFFF;
    box-shadow: 0 4px 14px rgba(99, 102, 241, 0.35);
}

.sl-btn-primary:hover {
    background: var(--sl-primary-hover);
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(99, 102, 241, 0.5);
    color: #FFFFFF;
}

.sl-btn-outline {
    background: rgba(255, 255, 255, 0.04);
    border-color: var(--sl-border);
    color: var(--sl-text-main);
}

.sl-btn-outline:hover {
    background: rgba(255, 255, 255, 0.09);
    border-color: rgba(255, 255, 255, 0.2);
    transform: translateY(-2px);
    color: #FFFFFF;
}

/* Stat Bar */
.sl-stat-bar {
    display: flex;
    align-items: center;
    gap: 2rem;
    padding-top: 2rem;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.sl-stat-box {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.sl-stat-value {
    font-size: 1.75rem;
    font-weight: 800;
    color: #FFFFFF;
    line-height: 1;
}

.sl-stat-label {
    font-size: 0.825rem;
    color: var(--sl-text-muted);
    font-weight: 500;
}

.sl-stat-divider {
    width: 1px;
    height: 36px;
    background: var(--sl-border);
}

/* Right Side Interactive Card */
.sl-hero-preview {
    perspective: 1000px;
}

.sl-interactive-card {
    background: var(--sl-surface);
    border: 1px solid var(--sl-border);
    border-radius: 20px;
    padding: 1.75rem;
    backdrop-filter: blur(20px);
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.7);
    transition: transform 0.3s ease, border-color 0.3s ease;
}

.sl-card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-bottom: 1.25rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    margin-bottom: 1.25rem;
}

.sl-card-identity {
    display: flex;
    align-items: center;
    gap: 12px;
}

.sl-identity-icon {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    background: rgba(99, 102, 241, 0.15);
    border: 1px solid rgba(99, 102, 241, 0.3);
    color: #818CF8;
    display: flex;
    align-items: center;
    justify-content: center;
}

.sl-card-title {
    font-size: 0.95rem;
    font-weight: 600;
    color: #FFFFFF;
}

.sl-card-status {
    font-size: 0.75rem;
    color: var(--sl-text-muted);
    display: flex;
    align-items: center;
    gap: 6px;
}

.sl-status-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--sl-success);
}

.sl-card-tag {
    font-size: 0.75rem;
    font-weight: 600;
    padding: 4px 10px;
    background: rgba(6, 182, 212, 0.12);
    border: 1px solid rgba(6, 182, 212, 0.3);
    color: #38BDF8;
    border-radius: 100px;
}

/* Chat Body */
.sl-messages-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    overflow: visible !important;
    max-height: none !important;
    margin-bottom: 1.25rem;
}

.sl-msg {
    display: flex;
    flex-direction: column;
    max-width: 88%;
    animation: slSlideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.sl-msg-ai {
    align-self: flex-start;
}

.sl-msg-user {
    align-self: flex-end;
}

.sl-msg-bubble {
    padding: 0.85rem 1.1rem;
    border-radius: 14px;
    font-size: 0.9rem;
    line-height: 1.5;
}

.sl-msg-ai .sl-msg-bubble {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.07);
    color: #F1F5F9;
    border-bottom-left-radius: 4px;
}

.sl-msg-user .sl-msg-bubble {
    background: var(--sl-primary);
    color: #FFFFFF;
    border-bottom-right-radius: 4px;
}

/* Prompt Chips */
.sl-prompt-chips {
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    padding-top: 1rem;
}

.sl-chip-label {
    display: block;
    font-size: 0.75rem;
    color: var(--sl-text-muted);
    margin-bottom: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    font-weight: 600;
}

.sl-chips-row {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.sl-chip-btn {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--sl-border);
    color: #E2E8F0;
    padding: 0.5rem 0.85rem;
    border-radius: 8px;
    font-family: inherit;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s ease;
}

.sl-chip-btn:hover {
    background: rgba(99, 102, 241, 0.2);
    border-color: rgba(99, 102, 241, 0.5);
    color: #FFFFFF;
    transform: translateY(-1px);
}

@keyframes slSlideIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Responsive */
@media (max-width: 992px) {
    .sl-hero-container {
        grid-template-columns: 1fr;
        gap: 3rem;
    }

    .sl-hero-title {
        font-size: clamp(2.2rem, 7vw, 3rem);
    }

    .sl-stat-bar {
        flex-wrap: wrap;
        gap: 1.25rem;
    }
}

