(function() {
    'use strict';

    function initSmartLearnHero() {
        // Find ALL instances of this section on the page
        const heroes = document.querySelectorAll('.sl-hero-wrapper');
        if (!heroes.length) return;

        heroes.forEach(hero => {
            // --- 1. INTERACTIVE PILL TABS ---
            const pills = hero.querySelectorAll('.sl-pill');
            const cardTitle = hero.querySelector('.sl-card-title-dynamic');
            const cardTag = hero.querySelector('.sl-card-tag-dynamic');
            const messageList = hero.querySelector('.sl-messages-list-dynamic');

            const tabData = {
                tutor: {
                    title: 'AI Tutor Neural Copilot',
                    tag: 'GPT-4o Adaptive',
                    initialMsg: "Hello! I've monitored your progress in <strong>Advanced Calculus</strong>. How can I assist your study session today?"
                },
                path: {
                    title: 'Adaptive Learning Path',
                    tag: 'Real-time Curriculum',
                    initialMsg: "Your diagnostic quiz indicates high proficiency in Linear Algebra. I have automatically unlocked <strong>Module 4: Matrix Transformations</strong>."
                },
                analytics: {
                    title: 'Predictive Exam Engine',
                    tag: '99.4% Accuracy',
                    initialMsg: "Based on your current retention curve, your projected final score is <strong>94% (Grade A)</strong>. Keep reviewing weekly flashcards!"
                }
            };

            pills.forEach(pill => {
                pill.addEventListener('click', function() {
                    pills.forEach(p => {
                        p.classList.remove('active');
                        p.setAttribute('aria-selected', 'false');
                    });
                    this.classList.add('active');
                    this.setAttribute('aria-selected', 'true');

                    const key = this.getAttribute('data-tab');
                    const data = tabData[key];
                    if (data && cardTitle && cardTag && messageList) {
                        cardTitle.textContent = data.title;
                        cardTag.textContent = data.tag;
                        messageList.innerHTML = `
                            <div class="sl-msg sl-msg-ai">
                                <div class="sl-msg-bubble">${data.initialMsg}</div>
                            </div>
                        `;
                    }
                });
            });

            // --- 2. INTERACTIVE CHAT DEMO ---
            const chipButtons = hero.querySelectorAll('.sl-chip-btn');
            chipButtons.forEach(btn => {
                btn.addEventListener('click', function() {
                    const promptText = this.getAttribute('data-prompt') || this.textContent;
                    if (!messageList) return;

                    const userMsg = document.createElement('div');
                    userMsg.className = 'sl-msg sl-msg-user';
                    userMsg.innerHTML = `<div class="sl-msg-bubble">${promptText}</div>`;
                    messageList.appendChild(userMsg);
                    messageList.scrollTop = messageList.scrollHeight;

                    setTimeout(() => {
                        const aiMsg = document.createElement('div');
                        aiMsg.className = 'sl-msg sl-msg-ai';

                        let replyText = "I'm analyzing your request and generating a tailored practice module right now...";
                        if (promptText.toLowerCase().includes('quiz')) {
                            replyText = "Here is Question 1 of 3: What is the integral of x * e^x dx? Take your time!";
                        } else if (promptText.toLowerCase().includes('study')) {
                            replyText = "I've structured a 45-minute daily schedule targeting your two weakest areas: Series & Limits.";
                        } else if (promptText.toLowerCase().includes('summarize')) {
                            replyText = "Summary: Today's lecture covered Taylor Polynomials and error bounds using Lagrange's form.";
                        }

                        aiMsg.innerHTML = `<div class="sl-msg-bubble">${replyText}</div>`;
                        messageList.appendChild(aiMsg);
                        messageList.scrollTop = messageList.scrollHeight;
                    }, 500);
                });
            });

            // --- 3. NUMBER COUNTER ANIMATION ---
            const counters = hero.querySelectorAll('.sl-stat-value');
            let animated = false;

            function animateCounters() {
                if (animated) return;
                animated = true;
                counters.forEach(counter => {
                    const target = parseInt(counter.getAttribute('data-target') || '0', 10);
                    const suffix = counter.getAttribute('data-suffix') || '';
                    let current = 0;
                    const increment = Math.max(1, Math.floor(target / 40));
                    const interval = setInterval(() => {
                        current += increment;
                        if (current >= target) {
                            current = target;
                            clearInterval(interval);
                        }
                        counter.textContent = current + suffix;
                    }, 30);
                });
            }

            if ('IntersectionObserver' in window) {
                const observer = new IntersectionObserver((entries) => {
                    if (entries[0].isIntersecting) {
                        animateCounters();
                        observer.disconnect();
                    }
                }, { threshold: 0.3 });
                observer.observe(hero);
            } else {
                animateCounters();
            }

            // --- 4. SUBTLE 3D TILT EFFECT ON CARD (Desktop Only) ---
            const card = hero.querySelector('.sl-interactive-card');
            if (card && window.matchMedia('(prefers-reduced-motion: no-preference)').matches && window.innerWidth > 992) {
                hero.addEventListener('mousemove', function(e) {
                    const rect = card.getBoundingClientRect();
                    const x = e.clientX - rect.left - rect.width / 2;
                    const y = e.clientY - rect.top - rect.height / 2;
                    card.style.transform = `rotateY(${x * 0.03}deg) rotateX(${-y * 0.03}deg)`;
                });

                hero.addEventListener('mouseleave', function() {
                    card.style.transform = 'rotateY(0deg) rotateX(0deg)';
                });
            }
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initSmartLearnHero);
    } else {
        initSmartLearnHero();
    }
})();
